<?php require_once __DIR__.'/../../app/layout.php';$a=require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['action']==='approve'?'approved':'rejected';$pdo->prepare('UPDATE donations SET status=?,approved_by=?,approved_at=NOW(),remarks=? WHERE id=? AND status="pending"')->execute([$status,$a['id'],trim($_POST['remarks']??''),$id]);if($status==='approved'){$p=$pdo->prepare('SELECT member_id,amount FROM donations WHERE id=?');$p->execute([$id]);$r=$p->fetch();if($r&&$r['member_id'])$pdo->prepare('INSERT IGNORE INTO acknowledgements (acknowledgement_no,member_id,payment_type,source_id,amount,issued_at) VALUES (?,?,?,?,?,NOW())')->execute(['DON/'.date('Y').'/'.str_pad((string)$id,6,'0',STR_PAD_LEFT),$r['member_id'],'donation',$id,$r['amount']]);}audit($pdo,$a['id'],'donation_'.$status,'donation',$id);flash('Donation '.$status.'.');redirect('/admin/donations.php');}
$rows=$pdo->query("SELECT d.*,COALESCE(m.full_name,d.donor_name) AS donor,COALESCE(mt.name,'Guest') AS member_type,COALESCE(m.district,d.donor_city) AS city,COALESCE(m.mobile,d.donor_mobile) AS mobile FROM donations d LEFT JOIN members m ON m.id=d.member_id LEFT JOIN membership_types mt ON mt.id=m.membership_type_id ORDER BY d.created_at DESC")->fetchAll();header_html('Donations');?>
<h1>Donations</h1><table><tr><th>Donor</th><th>Member Type</th><th>City</th><th>Mobile No</th><th>Purpose</th><th>Amount</th><th>Transaction</th><th>Status</th><th>Verify</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['donor'])?></td><td><?=e($r['member_type'])?></td><td><?=e((string)$r['city'])?></td><td><?=e((string)$r['mobile'])?></td><td><?=e($r['purpose'])?></td><td>₹<?=e($r['amount'])?></td><td><?=e((string)$r['transaction_no'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="remarks" placeholder="Remarks"><button name="action" value="approve">Approve</button><button name="action" value="reject">Reject</button></form><?php endif;?></td></tr><?php endforeach;?></table><?php footer_html();
